import jetbrains.mps.plugins.projectplugins.ProjectPluginManager;

public class ShowViewModelEntries_Action extends BaseAction {
  private static final Icon ICON = IconContainer.ICON0;

  public ShowViewModelEntries_Action() {
    super("Show View Model Entries", "Show the view model entries of the selected node, or of the closest node that has entries", ICON);
    this.setIsAlwaysVisible(false);
    this.setExecuteOutsideCommand(true);
    updateInBackground(true);
  }
  @Override
  public boolean isDumbAware() {
    return true;
  }
  @Override
  protected boolean collectActionData(AnActionEvent event, final Map<String, Object> _params) {
    if (!(super.collectActionData(event, _params))) {
      return false;
    }
    {
      SNode p = event.getData(MPSCommonDataKeys.NODE);
      if (p == null) {
        return false;
      }
    }
    {
      MPSProject p = event.getData(MPSCommonDataKeys.MPS_PROJECT);
      if (p == null) {
        return false;
      }
    }
    return true;
  }
  @Override
  public void doExecute(@NotNull final AnActionEvent event, final Map<String, Object> _params) {
    // The selected node when it has entries, otherwise the closest descendant or ancestor that has
    // (ViewModelsExplorer.closestNodeWithEntries). The tool window is filtered to that node.
    final SNode selected = event.getData(MPSCommonDataKeys.NODE);
    final SNodeReference[] target = new SNodeReference[1];
    final String[] description = new String[1];
    event.getData(MPSCommonDataKeys.MPS_PROJECT).getModelAccess().runReadAction(new Runnable() {
      public void run() {
        SNode found = ViewModelsExplorer.closestNodeWithEntries(selected);
        String selectedName = "'" + selected.getPresentation() + "'";
        if (found == null) {
          target[0] = selected.getReference();
          description[0] = "No view model entries for " + selectedName + ", its descendants or its ancestors";
        } else if (found == selected) {
          target[0] = found.getReference();
          description[0] = "Entries of " + selectedName;
        } else {
          target[0] = found.getReference();
          description[0] = "Entries of '" + found.getPresentation() + "' (" + found.getConcept().getName() + "), the closest node to " + selectedName + " that has entries";
        }
      }
    });
    final ViewModelsTool_Tool tool = ProjectPluginManager.getInstance(event.getData(MPSCommonDataKeys.MPS_PROJECT).getProject()).getTool(ViewModelsTool_Tool.class);
    tool.showEntriesOf(target[0], description[0]);
    tool.openToolLater(true);
  }
}
